    static String[] L() throws Exception {
        String[] a = new String(System.in.readAllBytes()).split("\n", -1);
        for (int i = 0; i < a.length; i++) if (a[i].endsWith("\r")) a[i] = a[i].substring(0, a[i].length() - 1);
        return a;
    }
    static String[] ps(String s) {
        java.util.List<String> o = new java.util.ArrayList<>();
        boolean in = false; StringBuilder c = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '"') { if (in) { o.add(c.toString()); c.setLength(0); in = false; } else in = true; }
            else if (in) c.append(ch);
        }
        return o.toArray(new String[0]);
    }
    public static void main(String[] args) throws Exception {
        String[] x = L();
        Solution sol = new Solution();
        System.out.println(sol.numIslands(ps(x[0])));
    }
}

