        for (int i = 0; i < p.length; i++) p[i] = p[i].trim();
        return p;
    }
    static TreeNode bt(String[] t) {
        if (t.length == 0 || t[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(t[0]));
