import java.util.*;

class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int x) { val = x; }
}

public class Main {
    static String[] L() throws Exception {
        String[] a = new String(System.in.readAllBytes()).split("\n", -1);
        for (int i = 0; i < a.length; i++) if (a[i].endsWith("\r")) a[i] = a[i].substring(0, a[i].length() - 1);
        return a;
    }
    static String[] pt(String s) {
        int a = s.indexOf('['), b = s.lastIndexOf(']');
        if (a >= 0 && b >= 0) s = s.substring(a + 1, b);
        s = s.trim();
        if (s.isEmpty()) return new String[0];
        String[] p = s.split(",");
        for (int i = 0; i < p.length; i++) p[i] = p[i].trim();
        return p;
    }
    static TreeNode bt(String[] t) {
        if (t.length == 0 || t[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(t[0]));
        Queue<TreeNode> q = new LinkedList<>(); q.add(root); int i = 1;
        while (i < t.length) {
            TreeNode n = q.poll();
            if (i < t.length) { if (!t[i].equals("null")) { n.left = new TreeNode(Integer.parseInt(t[i])); q.add(n.left); } i++; }
            if (i < t.length) { if (!t[i].equals("null")) { n.right = new TreeNode(Integer.parseInt(t[i])); q.add(n.right); } i++; }
        }
        return root;
    }
    static String st(TreeNode root) {
        if (root == null) return "[]";
        List<String> out = new ArrayList<>();
        Queue<TreeNode> q = new LinkedList<>(); q.add(root);
        while (!q.isEmpty()) {
            TreeNode n = q.poll();
            if (n == null) out.add("null");
            else { out.add(String.valueOf(n.val)); q.add(n.left); q.add(n.right); }
        }
        while (!out.isEmpty() && out.get(out.size() - 1).equals("null")) out.remove(out.size() - 1);
        StringBuilder b = new StringBuilder("[");
        for (int i = 0; i < out.size(); i++) { if (i > 0) b.append(','); b.append(out.get(i)); }
        return b.append(']').toString();
    }
    public static void main(String[] args) throws Exception {
        String[] x = L();
        Solution sol = new Solution();
        System.out.println(sol.isValidBST(bt(pt(x[0]))));
    }
}

