import java.util.*;

public class Main {
    static String[] L() throws Exception {
        String[] a = new String(System.in.readAllBytes()).split("\n", -1);
        for (int i = 0; i < a.length; i++) if (a[i].endsWith("\r")) a[i] = a[i].substring(0, a[i].length() - 1);
        return a;
    }
    static int[] pi(String s) {
        int a = s.indexOf('['), b = s.lastIndexOf(']');
        if (a >= 0 && b >= 0) s = s.substring(a + 1, b);
        s = s.trim();
        if (s.isEmpty()) return new int[0];
        String[] p = s.split(",");
        int[] r = new int[p.length];
        for (int i = 0; i < p.length; i++) r[i] = Integer.parseInt(p[i].trim());
        return r;
    }
    static int[][] pm(String s) {
        s = s.trim();
        int a = s.indexOf('['), b = s.lastIndexOf(']');
        if (a >= 0 && b >= 0) s = s.substring(a + 1, b);
        java.util.List<int[]> rows = new java.util.ArrayList<>();
        int i = 0;
        while (i < s.length()) {
            if (s.charAt(i) == '[') {
                int j = s.indexOf(']', i);
                String inner = s.substring(i + 1, j).trim();
                if (inner.isEmpty()) rows.add(new int[0]);
                else {
                    String[] p = inner.split(",");
                    int[] r = new int[p.length];
                    for (int k = 0; k < p.length; k++) r[k] = Integer.parseInt(p[k].trim());
                    rows.add(r);
                }
                i = j + 1;
            } else i++;
        }
        return rows.toArray(new int[0][]);
    }
    static String ia(int[] a) {
        StringBuilder b = new StringBuilder("[");
        for (int i = 0; i < a.length; i++) { if (i > 0) b.append(','); b.append(a[i]); }
        return b.append(']').toString();
    }
    static String im(int[][] m) {
        StringBuilder b = new StringBuilder("[");
        for (int i = 0; i < m.length; i++) {
            if (i > 0) b.append(',');
            b.append('[');
            for (int j = 0; j < m[i].length; j++) { if (j > 0) b.append(','); b.append(m[i][j]); }
            b.append(']');
        }
        return b.append(']').toString();
    }
    public static void main(String[] args) throws Exception {
        String[] x = L();
        Solution sol = new Solution();
        System.out.println(im(sol.merge(pm(x[0]))));
    }
}

