import java.util.*;

public class Main {
    static String[] L() throws Exception {
        String[] a = new String(System.in.readAllBytes()).split("\n", -1);
        for (int i = 0; i < a.length; i++) if (a[i].endsWith("\r")) a[i] = a[i].substring(0, a[i].length() - 1);
        return a;
    }
    static String sa(List<String> a) {
        StringBuilder b = new StringBuilder("[");
        for (int i = 0; i < a.size(); i++) {
            if (i > 0) b.append(',');
            b.append('"');
            for (char c : a.get(i).toCharArray()) { if (c == '\\' || c == '"') b.append('\\'); b.append(c); }
            b.append('"');
        }
        return b.append(']').toString();
    }
    public static void main(String[] args) throws Exception {
        String[] x = L();
        Solution sol = new Solution();
        System.out.println(sa(sol.letterCombinations(x[0])));
    }
}

